steps.script:
var mm = tree.root.get_node("/root/MainMenu")
mm._maybe_show_tutorial_nudge()
return true

var mm = tree.root.get_node("/root/MainMenu")
var scrim = mm.get_node_or_null("NudgeScrim")
if scrim == null:
	return "scrim missing"
if not scrim.visible:
	return "scrim hidden while nudge shown"
if scrim.mouse_filter != Control.MOUSE_FILTER_IGNORE:
	return "scrim intercepts mouse - nudge must stay non-modal"
var panel_bg = mm.get_node("TutorialNudge").get_theme_stylebox("panel").bg_color
var menu_bg = mm.get_node("Background").color
if panel_bg.is_equal_approx(menu_bg):
	return "panel bg identical to menu bg"
return "distinct"

var vp = tree.root.get_visible_rect().size
var n = tree.root.get_node("/root/MainMenu/TutorialNudge")
var r = n.get_global_rect()
if r.position.x < 0.0 or r.position.y < 0.0 or r.end.x > vp.x or r.end.y > vp.y:
	return "panel off-screen: %s in %s" % [str(r), str(vp)]
for bn in ["StartTrainingButton", "DismissNudgeButton"]:
	var b = n.get_node("Margin/VBox/Footer/" + bn).get_global_rect()
	if b.position.x < 0.0 or b.position.y < 0.0 or b.end.x > vp.x or b.end.y > vp.y:
		return "%s off-screen: %s in %s" % [bn, str(b), str(vp)]
return "on-screen"

var mm = tree.root.get_node("/root/MainMenu")
mm._maybe_show_tutorial_nudge()
return true
